/* Deterministic simulation. No network, paid APIs, or hidden services. */
window.LO = window.LO || {};
LO.rng = function(seed){return function(){seed|=0;seed=seed+0x6D2B79F5|0;var t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};};
LO.clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
LO.Core=class {
 constructor(saved){this.listeners=[];this.random=LO.rng(1999);this.state=saved||this.fresh();this.state.paused=true;this.state.lastReal=0;this.check();}
 fresh(){return {version:1,phase:'title',day:1,elapsed:0,duration:360,cash:140,reputation:72,heat:8,cleanliness:88,power:true,sodaWorking:true,fridgeWorking:true,inventory:{bun:20,beef:16,veggie:10,cheese:18,onion:18,potato:20,soda:24,coffee:24},grill:[],fryer:null,tray:{burger:null,fries:false,drink:null},assembly:{cheese:true,onion:false},queue:[],served:0,mistakes:0,revenue:0,waste:0,dayServed:0,dayMistakes:0,nextId:1,spawnAt:7,specialAt:48,specialArrived:false,missionRead:false,contactVerified:false,missionDone:false,fakeResolved:false,inspectorDone:false,coverAnswered:false,stormDone:false,shortMenu:false,documentsSecure:true,events:[],eventAt:65,eventHistory:[],facts:[],reports:[],relations:{mara:0,mina:0,nico:0,cole:0,vera:0,iris:0,driver:0},upgrades:{grill:0,fryer:0,fridge:0},log:[],lastMessage:'Welcome to Starline Burger.',settings:{captions:true,sound:true,slow:false,reduceMotion:false,timedBrief:true},ending:null,paused:true,stats:{replays:0,clarifications:0,notices:0,helped:0,reportsWritten:0},seed:1999};}
 check(){let s=this.state;s.cash=Number(s.cash)||0;s.elapsed=Number(s.elapsed)||0;for(let k of ['reputation','heat','cleanliness'])s[k]=LO.clamp(Number(s[k])||0,0,100);}
 on(fn){this.listeners.push(fn);} emit(type,data){for(let fn of this.listeners)fn(type,data);}
 message(text){this.state.lastMessage=text;this.emit('message',text);}
 log(text){let s=this.state;s.log.unshift({day:s.day,time:this.clock(),text});s.log=s.log.slice(0,100);}
 save(){try{localStorage.setItem('last-order-save',JSON.stringify(this.state));return true;}catch(e){return false;}}
 clock(){let m=8*60+Math.floor(this.state.elapsed/this.state.duration*12*60);return String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(m%60).padStart(2,'0');}
 begin(){this.state.briefRemaining=90;this.state.phase='brief';this.state.paused=true;this.emit('phase','brief');this.save();}
 open(){let s=this.state;s.phase='open';s.paused=false;s.missionRead=true;this.message('The shop is open. Listen to the first order at the counter.');this.log('Opened the shop.');this.emit('phase','open');this.save();}
 tick(dt){let s=this.state;if(s.phase!=='open'||s.paused)return;dt=LO.clamp(dt,0,1);s.elapsed+=dt;s.cleanliness=LO.clamp(s.cleanliness-dt*.022,0,100);
  if(s.power){for(let p of s.grill){p.time+=dt;if(p.time>=8-(s.upgrades.grill?2:0)&&p.status==='raw')p.status='ready';if(p.time>=23)p.status='burnt';}if(s.fryer){s.fryer.time+=dt;if(s.fryer.time>=7-(s.upgrades.fryer?2:0)&&s.fryer.status==='raw')s.fryer.status='ready';if(s.fryer.time>=25)s.fryer.status='burnt';}}
  for(let c of s.queue)c.patience-=dt*(s.settings.slow?.56:1)*(s.shortMenu?.8:1);for(let c of [...s.queue])if(c.patience<=0){s.queue=s.queue.filter(x=>x.uid!==c.uid);s.reputation-=c.mission?3:5;s.mistakes++;s.dayMistakes++;this.log(LO.NPCS[c.npc].name+' left after waiting.');if(c.mission){s.specialAt=s.elapsed+25;s.specialArrived=false;}this.message('A customer left. Keep the queue moving.');}
  if(s.elapsed>=s.spawnAt&&s.queue.length<(s.shortMenu?2:4)&&s.elapsed<s.duration-30){this.spawn();s.spawnAt=s.elapsed+27+this.random()*15;}
  if(!s.specialArrived&&s.elapsed>=s.specialAt&&s.queue.length<4){this.spawn(LO.DAYS[s.day-1].special,true);s.specialArrived=true;}
  if(s.day===2&&!s.fakeResolved&&s.elapsed>25&&!s.queue.some(c=>c.fake)){this.spawn('office',false,true);}
  if(s.day===4&&!s.stormDone&&s.elapsed>s.duration*.35){s.stormDone=true;s.power=false;this.event('storm','The lights go out','The storm has tripped the breaker. Grills and fryers have stopped. Keep the fridge closed and reset the breaker.', 'power','Reset the breaker',95);this.emit('sound','storm');}
  if(s.elapsed>=s.eventAt&&s.events.length<2&&s.elapsed<s.duration-35){let pool=LO.EVENTS.filter(e=>!s.eventHistory.includes(e.id));if(!pool.length)pool=LO.EVENTS;let e=pool[Math.floor(this.random()*pool.length)];this.trigger(e);s.eventAt=s.elapsed+65+this.random()*30;}
  for(let e of [...s.events]){e.remaining-=dt;if(e.remaining<=0)this.expire(e);}
  if(s.elapsed>=s.duration){if(s.endless){s.elapsed=0;s.cash-=18;s.spawnAt=4;s.eventAt=40;s.events=[];this.message('A new service shift begins. Daily overhead paid.');this.save();}else this.close();}this.check();this.emit('tick');}
 spawn(npc,mission=false,fake=false){let s=this.state;let names=['driver','mechanic','office','tourist','mina','iris'];npc=npc||names[Math.floor(this.random()*names.length)];let order=JSON.parse(JSON.stringify(LO.ORDER_LINES[Math.floor(this.random()*LO.ORDER_LINES.length)]));if(!s.sodaWorking&&order.drink==='soda'){order.drink='coffee';order.line='A cheeseburger, no onions, fries, and a coffee. The soda machine looks tired.';order.kind='beef';order.cheese=true;order.onion=false;order.fries=true;}
  if(s.shortMenu){order={kind:'beef',cheese:true,onion:false,fries:false,drink:'coffee',line:'A cheeseburger, no onions, and a coffee from the short menu, please.'};}
  let c={uid:s.nextId++,npc,order,patience:mission?160:125,maxPatience:mission?160:125,heard:false,mission,fake,serviceDone:false};s.queue.push(c);this.emit('arrival',c);return c;}
 hear(uid){let c=this.state.queue.find(c=>c.uid===uid);if(!c)return null;if(c.heard)this.state.stats.replays++;c.heard=true;this.emit('speech',{npc:c.npc,text:c.order.line});return c.order.line;}
 clarify(uid){let c=this.state.queue.find(c=>c.uid===uid);if(!c)return;this.state.stats.clarifications++;let o=c.order;let line='To confirm: '+(o.kind==='veggie'?'veggie burger':'beef burger')+', '+(o.cheese?'with cheese':'no cheese')+', '+(o.onion?'with onions':'no onions')+'. '+(o.fries?'Fries. ':'No fries. ')+(o.drink?o.drink+'.':'No drink.');c.heard=true;this.emit('speech',{npc:c.npc,text:line});this.message('You asked the customer to clarify.');}
 cook(kind){let s=this.state;if(!s.power)return this.message('The power is off. Reset the breaker.');if(!s.fridgeWorking)return this.message('Isolate and repair the fridge before using this stock.');if(s.grill.length>=2+(s.upgrades.grill?1:0))return this.message('Both grill slots are occupied.');if(s.inventory[kind]<=0)return this.message('Out of '+kind+' patties. Order supplies in the office.');s.inventory[kind]--;s.grill.push({kind,time:0,status:'raw'});this.emit('sound','cook');this.message('Patty on the grill. It will be ready in '+(s.upgrades.grill?6:8)+' seconds.');}
 fry(){let s=this.state;if(!s.power)return this.message('The fryer has no power.');if(s.fryer)return this.message('A basket is already cooking.');if(!s.inventory.potato)return this.message('No potatoes left.');s.inventory.potato--;s.fryer={time:0,status:'raw'};this.emit('sound','cook');}
 assemble(index){let s=this.state,p=s.grill[index];if(!p)return;if(p.status==='raw')return this.message('That patty is still raw.');if(s.tray.burger)return this.message('The tray already has a burger. Serve it or clear the tray.');if(s.inventory.bun<=0)return this.message('No buns. Check the storeroom.');let a=s.assembly;if(a.cheese&&s.inventory.cheese<=0)return this.message('No cheese left.');if(a.onion&&s.inventory.onion<=0)return this.message('No onions left.');s.inventory.bun--;if(a.cheese)s.inventory.cheese--;if(a.onion)s.inventory.onion--;s.tray.burger={kind:p.kind,cheese:a.cheese,onion:a.onion,burnt:p.status==='burnt'};s.grill.splice(index,1);this.message(p.status==='burnt'?'A burnt burger is on the tray. You can discard it.':'Burger assembled and placed on the tray.');this.emit('sound','click');}
 takeFries(){let s=this.state;if(!s.fryer)return;if(s.fryer.status==='raw')return this.message('The fries are not cooked yet.');if(s.tray.fries)return this.message('The tray already has fries.');s.tray.fries=true;s.tray.burntFries=s.fryer.status==='burnt';s.fryer=null;this.message('Fries added to the tray.');}
 drink(kind){let s=this.state;if(kind==='soda'&&!s.sodaWorking)return this.message('The soda machine needs a repair.');if(s.inventory[kind]<=0)return this.message('Out of '+kind+'.');if(s.tray.drink)return this.message('The tray already has a drink.');s.inventory[kind]--;s.tray.drink=kind;this.message(kind==='coffee'?'Coffee added to the tray.':'Soda added to the tray.');}
 clearTray(){let s=this.state;if(s.tray.burger||s.tray.fries||s.tray.drink){s.waste++;s.cash-=1;s.cleanliness-=1;}s.tray={burger:null,fries:false,drink:null};this.message('Tray cleared. Discarded food cannot be recovered.');}
 matchOrder(c){let t=this.state.tray,o=c.order,errors=[];if(!t.burger)errors.push('missing burger');else{if(t.burger.kind!==o.kind)errors.push('wrong patty');if(t.burger.cheese!==o.cheese)errors.push(o.cheese?'missing cheese':'unwanted cheese');if(t.burger.onion!==o.onion)errors.push(o.onion?'missing onions':'unwanted onions');if(t.burger.burnt)errors.push('burnt patty');}if(!!t.fries!==o.fries)errors.push(o.fries?'missing fries':'unwanted fries');if(t.burntFries)errors.push('burnt fries');if(t.drink!==o.drink)errors.push('wrong or missing drink');return errors;}
 serve(uid){let s=this.state,c=s.queue.find(c=>c.uid===uid);if(!c)return;if(c.serviceDone)return this.message('This order has already been paid and served.');let errors=this.matchOrder(c);if(errors.length){s.mistakes++;s.dayMistakes++;s.reputation-=2;c.patience=Math.max(30,c.patience-12);this.message('Order needs a remake: '+errors.join(', ')+'.');this.emit('serviceError',errors);return false;}let total=4.5+(c.order.cheese?.5:0)+(c.order.fries?2:0)+(c.order.drink?1.5:0);s.cash+=total;s.revenue+=total;s.served++;s.dayServed++;s.reputation=LO.clamp(s.reputation+2,0,100);s.relations[c.npc]=(s.relations[c.npc]||0)+1;s.cleanliness-=.8;s.tray={burger:null,fries:false,drink:null};c.serviceDone=true;
  if(!c.mission&&!c.fake)s.queue=s.queue.filter(x=>x.uid!==uid);else c.patience=Math.max(c.patience,100);
  this.log('Served '+LO.NPCS[c.npc].name+' · $'+total.toFixed(2));this.message('Order correct. '+LO.NPCS[c.npc].name+' paid $'+total.toFixed(2)+'.');this.emit('sound','sale');this.save();return true;}
 verifyContact(uid){let s=this.state,c=s.queue.find(c=>c.uid===uid);if(!c)return;if(c.fake){s.fakeResolved=true;s.heat=LO.clamp(s.heat-3,0,100);s.queue=s.queue.filter(x=>x.uid!==uid);this.addFact(LO.DAYS[1].facts[0]);this.message('The pickup slip is expired. You decline the release without making an unsupported accusation.');this.log('Rejected the expired Northline pickup.');return;}
  if(!c.mission)return this.message('This is an ordinary customer. Keep your cover and serve their order.');s.contactVerified=true;this.emit('speech',{npc:c.npc,text:LO.DAYS[s.day-1].line});this.message('The contact has been verified. Hear the full message, then collect the documents.');}
 collect(uid){let s=this.state,c=s.queue.find(c=>c.uid===uid);if(!c||!c.mission)return;if(!s.contactVerified)return this.message('Verify the contact before accepting a handoff.');if(!c.serviceDone)return this.message('Complete the cover order before the handoff.');for(let f of LO.DAYS[s.day-1].facts)this.addFact(f);s.missionDone=true;s.documentsSecure=false;s.relations[c.npc]=(s.relations[c.npc]||0)+2;s.queue=s.queue.filter(x=>x.uid!==uid);this.log('Collected the day’s evidence.');this.message('Evidence recorded. Secure the papers in the office.');this.save();}
 addFact(f){if(!this.state.facts.some(x=>x.id===f.id)){this.state.facts.push({...f,day:this.state.day});this.emit('evidence',f);}}
 event(id,title,text,action,actionLabel,seconds){let e={id,title,text,action,actionLabel,remaining:seconds};this.state.events.push(e);this.state.eventHistory.push(id);this.log(title);this.emit('event',e);return e;}
 trigger(e){let s=this.state;if(e.id==='soda')s.sodaWorking=false;if(e.id==='fridge'){s.fridgeWorking=false;if(s.upgrades.fridge){s.fridgeWorking=true;return this.message('The insulated fridge holds steady. Your upgrade prevented a stock loss.');}}if(e.id==='cleaner')s.documentsSecure=false;if(e.id==='shortage')s.inventory.potato=Math.min(s.inventory.potato,2);if(e.id==='rush'){for(let i=0;i<2&&s.queue.length<4;i++)this.spawn();}this.event(e.id,e.title,e.text,e.action,e.actionLabel,e.seconds);}
 resolve(id,notice){let s=this.state,e=s.events.find(e=>e.id===id);if(!e)return false;let cost={repairSoda:6,repairFridge:8,meal:4,review:3}[e.action]||0;if(s.cash<cost)return this.message('Not enough cash. Keep serving orders or choose a cheaper response.');
  if(e.action==='notice'){if(!notice||!/(?:out of|unavailable|no|sold out|short)/i.test(notice)||!/(?:fries|potato)/i.test(notice))return this.message('Make the notice clear: mention that fries or potatoes are unavailable.');s.stats.notices++;s.notice=notice;s.reputation+=2;}
  s.cash-=cost;if(e.action==='power')s.power=true;if(e.action==='repairSoda')s.sodaWorking=true;if(e.action==='repairFridge'){s.fridgeWorking=true;s.inventory.beef=Math.max(0,s.inventory.beef-2);s.inventory.veggie=Math.max(0,s.inventory.veggie-1);}if(e.action==='secure')s.documentsSecure=true;if(e.action==='askMina'){s.relations.mina+=2;for(let c of s.queue)c.patience+=30;}if(e.action==='meal'){s.relations.driver+=3;s.stats.helped++;}if(e.action==='shortMenu')s.shortMenu=true;if(e.action==='verify'||e.action==='verifyCaller'){s.heat-=3;s.stats.clarifications++;}if(e.action==='recoverBag')s.heat-=2;
  s.events=s.events.filter(x=>x!==e);s.reputation=LO.clamp(s.reputation+1,0,100);this.message('Resolved: '+e.title+'.');this.log('Resolved '+e.title.toLowerCase()+'.');this.emit('sound','success');this.save();return true;}
 expire(e){let s=this.state;s.events=s.events.filter(x=>x!==e);s.reputation-=3;if(e.action==='secure'&&!s.documentsSecure)s.heat+=10;if(e.action==='recoverBag')s.heat+=7;if(e.action==='repairFridge'){s.inventory.beef=Math.max(0,s.inventory.beef-3);s.fridgeWorking=true;}if(e.action==='power'){s.power=true;s.inventory.beef=Math.max(0,s.inventory.beef-2);}if(e.action==='repairSoda')s.sodaWorking=true;this.message('Missed event: '+e.title+'. There will be another chance to recover.');}
 clean(){let s=this.state;s.cleanliness=LO.clamp(s.cleanliness+18,0,100);this.message('Tables wiped, food surfaces cleaned, and waste removed.');this.emit('sound','clean');}
 secure(){this.state.documentsSecure=true;let e=this.state.events.find(e=>e.action==='secure');if(e)this.resolve(e.id);else this.message('Documents secured in the office cabinet.');}
 inspect(){let s=this.state;if(s.inspectorDone)return this.message('The inspection has already been signed off.');if(!LO.DAYS[s.day-1].inspection)return this.message('No scheduled inspection today. Keep the kitchen ready.');if(s.cleanliness<65||!s.fridgeWorking){s.heat+=3;this.message('Vera asks you to clean and repair the fridge before she can sign off.');return false;}s.inspectorDone=true;s.relations.vera+=2;s.reputation+=2;this.message('Hygiene inspection passed. Vera signs the log.');return true;}
 cover(text){let s=this.state;if(s.coverCorrect)return this.message('Cole already has your consistent account.');let ok=/alex/i.test(text)&&/monday/i.test(text)&&/mara/i.test(text);s.coverAnswered=true;if(ok){s.coverCorrect=true;s.heat=Math.max(0,s.heat-5);s.relations.cole+=2;this.message('Your account matches the staff rota. Cole records it.');}else{s.heat+=7;this.message('Cole spots a mismatch. Your cover card is in the notebook; you can correct the record.');}return ok;}
 restock(key){let prices={bun:5,beef:9,veggie:7,cheese:4,onion:3,potato:5,soda:4,coffee:4};let s=this.state;if(s.cash<prices[key])return this.message('Not enough cash for that delivery.');s.cash-=prices[key];s.inventory[key]+=10;this.log('Restocked '+key+' · 10 units.');this.message('Delivery received: 10 '+key+'.');}
 upgrade(key){let s=this.state,price={grill:45,fryer:35,fridge:40}[key];if(s.upgrades[key])return this.message('That upgrade is already installed.');if(s.cash<price)return this.message('Earn a little more before buying this upgrade.');s.cash-=price;s.upgrades[key]=1;this.message('Installed '+key+' upgrade.');this.save();}
 close(){let s=this.state;if(s.phase!=='open')return;s.phase='report';s.paused=true;s.cash-=18;s.events=[];s.queue=[];if(!s.missionDone){s.heat+=6;this.log('The handoff was missed. A recovered file is available for a partial report.');let f=LO.DAYS[s.day-1].facts[0];if(f)this.addFact({...f,confirmed:false,source:'Recovered partial file · not a completed handoff'});}if(!s.documentsSecure)s.heat+=4;this.emit('phase','report');this.save();}
 evaluate(text){let d=LO.DAYS[this.state.day-1],clean=text.toLowerCase().replace(/[’]/g,"'").replace(/\s+/g,' ');let words=text.trim().split(/\s+/).filter(Boolean).length;let checks=d.checks.map(c=>{let re=new RegExp(c.re,'gi'),m,pass=false;while((m=re.exec(clean))!==null){let before=clean.slice(Math.max(0,m.index-20),m.index);if(!/\b(?:not|never|isn't|wasn't|is not|was not)\s*(?:be\s+)?(?:at\s+|to\s+)?(?:the\s+)?$/.test(before)){pass=true;break;}}return{id:c.id,label:c.label,pass};});return {words,checks,score:Math.round(checks.filter(c=>c.pass).length/checks.length*100),tooShort:words<15};}
 submitReport(text){let s=this.state;if(s.reports.some(r=>r.day===s.day))return null;let result=this.evaluate(text);if(result.tooShort){this.message('Write at least 15 words so the recipient has enough context.');return null;}s.reports.push({day:s.day,text,result});s.stats.reportsWritten++;if(result.score>=75)s.heat=Math.max(0,s.heat-4);else s.heat+=4;this.log('Filed report · essential facts '+result.score+'%.');this.save();return result;}
 nextDay(){let s=this.state;if(s.day>=5){s.phase='decision';this.emit('phase','decision');return;}s.day++;s.elapsed=0;s.dayServed=0;s.dayMistakes=0;s.queue=[];s.events=[];s.grill=[];s.fryer=null;s.tray={burger:null,fries:false,drink:null};s.spawnAt=7;s.eventAt=65;s.specialAt=48;s.specialArrived=false;s.contactVerified=false;s.missionDone=false;s.fakeResolved=false;s.inspectorDone=false;s.coverAnswered=false;s.coverCorrect=false;s.documentsSecure=true;s.stormDone=false;s.shortMenu=false;s.power=true;s.sodaWorking=true;s.fridgeWorking=true;s.cleanliness=Math.max(65,s.cleanliness);s.briefRemaining=90;s.phase='brief';s.paused=true;this.emit('phase','brief');this.save();}
 end(choice){let s=this.state,report=s.reports[s.reports.length-1],score=report?report.result.score:0,corroborated=s.facts.some(f=>f.id==='D4_FORGED')&&score>=75;let endings={press:{title:corroborated?'THE CITY LEARNS YOUR ORDER':'AN INCOMPLETE EDITION',body:corroborated?'Iris publishes the altered records with names and addresses removed. Cole has enough corroboration to halt the transport. The witnesses stay people, not a list.':'Iris publishes carefully, but the gaps in the brief slow verification. Some witnesses get away; the story is still developing.'},cole:{title:corroborated&&s.heat<75?'ON THE RECORD':'PENDING REVIEW',body:corroborated&&s.heat<75?'Cole challenges the order with documentary evidence. The van stays at the depot. You leave your statements on the record and the witnesses off the public page.':'Cole opens an inquiry, but cannot stop everything on an incomplete or contradictory account. The evidence survives for another day.'},control:{title:'DELIVERED AS REQUESTED',body:'Control receives the unredacted list and calls the operation a success. Nico disappears from the queue. The official file says nothing about where the witnesses went.'},protect:{title:s.relations.nico>=4?'A TABLE KEPT OPEN':'ROOM FOR ONE MORE',body:s.relations.nico>=4?'With Nico and the neighborhood’s help, the witnesses find a safe route. Iris keeps working on the evidence. You saved people before you finished a case.':'You help Nico find a way out, although the scattered evidence leaves the wider case unresolved. Mara keeps a light on for anyone still missing.'}};s.ending={...endings[choice],choice,shop:s.cash>=0&&s.reputation>=40?'Starline Burger opens again on Saturday.':'Mara closes for repairs. The neighborhood brings what it can.'};s.phase='ending';s.paused=true;this.emit('phase','ending');this.save();}
 endless(){let s=this.state;s.phase='open';s.paused=false;s.elapsed=0;s.specialArrived=true;s.specialAt=1000000000;s.spawnAt=4;s.eventAt=40;s.duration=600;s.endless=true;s.events=[];s.queue=[];this.emit('phase','open');}
 export(){return JSON.stringify(this.state,null,2);}
};
